// Exception safety - automatic deallocation on constructor failure:
try {
    Widget* w = new Widget(args);  // Allocation succeeds, constructor throws
} catch (...) {
    // Memory automatically freed via operator delete before exception propagates
}

// Placement new requires matching placement delete:
class Arena { /* ... */ };

void* operator new(size_t size, Arena& arena);    // Placement allocation
void operator delete(void* ptr, Arena& arena);    // Matching placement deallocation

try {
    Widget* w = new (myArena) Widget(args);  // If constructor throws,
                                              // calls operator delete(ptr, myArena)
} catch (...) { /* ... */ }

// Non-throwing allocation:
Widget* w = new (std::nothrow) Widget;  // Returns nullptr on failure
if (!w) { /* handle allocation failure */ }

// Ill-formed example:
struct S {
    static void* operator new(size_t, size_t);  // Placement allocation
    static void operator delete(void*, size_t); // Usual (sized) deallocation
};
S* p = new (0) S;  // ERROR: Ill-formed (sized delete matches placement new)

code_example:
#include <iostream>
#include <new>
#include <stdexcept>

// Custom arena allocator
class Arena {
public:
    void* allocate(size_t size) {
        std::cout << "  Arena::allocate(" << size << ")\n";
        return std::malloc(size);
    }
    void deallocate(void* ptr) {
        std::cout << "  Arena::deallocate(" << ptr << ")\n";
        std::free(ptr);
    }
};

// Placement allocation/deallocation for Arena
void* operator new(size_t size, Arena& arena) {
    std::cout << "operator new(" << size << ", Arena&)\n";
    return arena.allocate(size);
}

// Matching placement deallocation (called on constructor exception)
void operator delete(void* ptr, Arena& arena) noexcept {
    std::cout << "operator delete(void*, Arena&) - exception cleanup\n";
    arena.deallocate(ptr);
}

// Also provide usual deallocation for normal delete
void operator delete(void* ptr) noexcept {
    std::cout << "operator delete(void*) - normal cleanup\n";
    std::free(ptr);
}

class FailingWidget {
public:
    FailingWidget(bool should_fail) {
        std::cout << "  FailingWidget() constructor\n";
        if (should_fail) {
            std::cout << "  Constructor throwing exception!\n";
            throw std::runtime_error("Construction failed");
        }
    }
    ~FailingWidget() {
        std::cout << "  ~FailingWidget() destructor\n";
    }
};

int main() {
    Arena myArena;

    std::cout << "=== Exception Safety Demo ===\n\n";

    // Case 1: Constructor succeeds
    std::cout << "1. Successful construction:\n";
    try {
        FailingWidget* w = new (myArena) FailingWidget(false);
        std::cout << "Success! Now deleting normally...\n";
        delete w;  // Calls usual operator delete (NOT placement delete)
    } catch (std::exception& e) {
        std::cout << "Caught: " << e.what() << "\n";
    }

    // Case 2: Constructor throws - automatic deallocation
    std::cout << "\n2. Constructor throws exception:\n";
    try {
        FailingWidget* w = new (myArena) FailingWidget(true);
        std::cout << "This line never executes\n";
    } catch (std::exception& e) {
        std::cout << "Caught: " << e.what() << "\n";
        std::cout << "Notice: placement delete was automatically called!\n";
    }

    // Case 3: Non-throwing allocation
    std::cout << "\n3. Non-throwing allocation (std::nothrow):\n";
    FailingWidget* w2 = new (std::nothrow) FailingWidget(false);
    if (w2) {
        std::cout << "Allocation succeeded, returned non-null\n";
        delete w2;
    } else {
        std::cout << "Allocation failed, returned nullptr\n";
    }

    // Case 4: Demonstrate memory leak without matching delete
    std::cout << "\n4. Memory leak scenario (no matching placement delete):\n";
    std::cout << "If there were NO placement delete defined, the memory\n";
    std::cout << "from case 2 would have leaked when constructor threw!\n";

    return 0;
}

// Output:
// === Exception Safety Demo ===
//
// 1. Successful construction:
// operator new(1, Arena&)
//   Arena::allocate(1)
//   FailingWidget() constructor
// Success! Now deleting normally...
//   ~FailingWidget() destructor
// operator delete(void*) - normal cleanup
//
// 2. Constructor throws exception:
// operator new(1, Arena&)
//   Arena::allocate(1)
//   FailingWidget() constructor
//   Constructor throwing exception!
// operator delete(void*, Arena&) - exception cleanup  <- Automatic!
//   Arena::deallocate(0x...)
// Caught: Construction failed
// Notice: placement delete was automatically called!
//
// 3. Non-throwing allocation (std::nothrow):
//   FailingWidget() constructor
// Allocation succeeded, returned non-null
//   ~FailingWidget() destructor
// operator delete(void*) - normal cleanup
//
// 4. Memory leak scenario (no matching placement delete):
// If there were NO placement delete defined, the memory
// from case 2 would have leaked when constructor threw!
